if (element.querySelector('.advanced-filter-chips')) return;

var wrapper = document.createElement('div');
wrapper.className = 'advanced-filter-chips';
wrapper.style.cssText = 'display:flex;flex-wrap:wrap;gap:6px;padding:8px 16px 0;border-top:1px solid rgba(255,255,255,0.1);margin-top:4px;';

var chips = [
  { label: '📹 Any type', category: 'type' },
  { label: '⏱ Any duration', category: 'duration' },
  { label: '📅 Any time', category: 'time' },
  { label: '✨ Any feature', category: 'feature' },
  { label: '🔼 Sort by', category: 'sort' },
  { label: '🎬 Movie', category: 'type' },
  { label: '📺 Show', category: 'type' },
  { label: '📻 Channel', category: 'type' },
  { label: '< 4 min', category: 'duration' },
  { label: '4-20 min', category: 'duration' },
  { label: '> 20 min', category: 'duration' },
  { label: 'Last hour', category: 'time' },
  { label: 'Today', category: 'time' },
  { label: 'This week', category: 'time' },
  { label: 'This month', category: 'time' },
  { label: 'This year', category: 'time' },
  { label: '4K', category: 'feature' },
  { label: 'HD', category: 'feature' },
  { label: 'Subtitles/CC', category: 'feature' },
  { label: 'Live', category: 'feature' },
  { label: 'Location', category: 'feature' },
  { label: 'Relevance', category: 'sort' },
  { label: 'Rating', category: 'sort' },
  { label: 'Upload date', category: 'sort' },
  { label: 'View count', category: 'sort' }
];

chips.forEach(function(chipData) {
  var chip = document.createElement('button');
  chip.className = 'yt-advanced-filter-chip';
  chip.textContent = chipData.label;
  chip.style.cssText = 'display:inline-flex;align-items:center;gap:4px;padding:6px 12px;border-radius:8px;border:1px solid rgba(255,255,255,0.2);background:rgba(255,255,255,0.08);color:#f1f1f1;font-size:13px;font-weight:500;cursor:pointer;white-space:nowrap;transition:all 0.2s ease;font-family:Roboto,Arial,sans-serif;';

  chip.addEventListener('mouseenter', function() {
    this.style.background = 'rgba(255,255,255,0.18)';
    this.style.borderColor = 'rgba(255,255,255,0.4)';
  });
  chip.addEventListener('mouseleave', function() {
    if (!this.classList.contains('yt-advanced-filter-chip-active')) {
      this.style.background = 'rgba(255,255,255,0.08)';
      this.style.borderColor = 'rgba(255,255,255,0.2)';
    }
  });

  var self = chip;
  chip.addEventListener('click', function() {
    var category = chipData.category;
    var allChips = wrapper.querySelectorAll('.yt-advanced-filter-chip');

    if (category === 'type' || category === 'duration' || category === 'time' || category === 'feature') {
      allChips.forEach(function(c) {
        var cText = c.textContent.trim();
        var isActive = c.classList.contains('yt-advanced-filter-chip-active');

        if (c !== self && isActive) {
          var otherChipData = chips.find(function(cd) { return cd.label === cText; });
          if (otherChipData && otherChipData.category === category) {
            c.classList.remove('yt-advanced-filter-chip-active');
            c.style.background = 'rgba(255,255,255,0.08)';
            c.style.borderColor = 'rgba(255,255,255,0.2)';
            c.style.color = '#f1f1f1';
          }
        }
      });

      if (self.classList.contains('yt-advanced-filter-chip-active')) {
        self.classList.remove('yt-advanced-filter-chip-active');
        self.style.background = 'rgba(255,255,255,0.08)';
        self.style.borderColor = 'rgba(255,255,255,0.2)';
        self.style.color = '#f1f1f1';
      } else {
        self.classList.add('yt-advanced-filter-chip-active');
        self.style.background = 'rgba(34,197,94,0.25)';
        self.style.borderColor = 'rgb(34,197,94)';
        self.style.color = '#4ade80';
      }
    } else if (category === 'sort') {
      allChips.forEach(function(c) {
        var cText = c.textContent.trim();
        var otherChipData = chips.find(function(cd) { return cd.label === cText; });
        if (otherChipData && otherChipData.category === 'sort') {
          c.classList.remove('yt-advanced-filter-chip-active');
          c.style.background = 'rgba(255,255,255,0.08)';
          c.style.borderColor = 'rgba(255,255,255,0.2)';
          c.style.color = '#f1f1f1';
        }
      });

      self.classList.add('yt-advanced-filter-chip-active');
      self.style.background = 'rgba(59,130,246,0.25)';
      self.style.borderColor = 'rgb(59,130,246)';
      self.style.color = '#60a5fa';
    }
  });

  wrapper.appendChild(chip);
});

element.appendChild(wrapper);

if (element.querySelector('.persistent-filters-panel')) return;

var panel = document.createElement('div');
panel.className = 'persistent-filters-panel';
panel.style.cssText = 'display:flex;flex-wrap:wrap;gap:12px;padding:8px 0 4px;align-items:flex-start;';

var categories = [
  {
    title: 'Type',
    options: ['All types', 'Video', 'Channel', 'Playlist', 'Movie', 'Show']
  },
  {
    title: 'Duration',
    options: ['Any duration', 'Under 4 minutes', '4 - 20 minutes', 'Over 20 minutes']
  },
  {
    title: 'Upload date',
    options: ['Any time', 'Last hour', 'Today', 'This week', 'This month', 'This year']
  },
  {
    title: 'Features',
    options: ['Any feature', '4K', 'HD', 'Subtitles/CC', 'Live', 'Creative Commons', 'Location']
  },
  {
    title: 'Sort by',
    options: ['Relevance', 'Upload date', 'View count', 'Rating']
  }
];

categories.forEach(function(cat) {
  var group = document.createElement('div');
  group.style.cssText = 'display:flex;flex-direction:column;gap:4px;';

  var label = document.createElement('div');
  label.textContent = cat.title;
  label.style.cssText = 'font-size:11px;font-weight:700;text-transform:uppercase;color:#aaa;letter-spacing:0.5px;margin-bottom:2px;';
  group.appendChild(label);

  var optionsContainer = document.createElement('div');
  optionsContainer.style.cssText = 'display:flex;flex-direction:column;gap:3px;';

  cat.options.forEach(function(opt) {
    var btn = document.createElement('button');
    btn.textContent = opt;
    btn.style.cssText = 'display:block;text-align:left;padding:5px 10px;border-radius:6px;border:none;background:rgba(255,255,255,0.06);color:#f1f1f1;font-size:12.5px;cursor:pointer;transition:all 0.15s ease;font-family:Roboto,Arial,sans-serif;width:100%;white-space:nowrap;';

    btn.addEventListener('mouseenter', function() {
      this.style.background = 'rgba(255,255,255,0.14)';
    });
    btn.addEventListener('mouseleave', function() {
      if (!this.classList.contains('filter-active')) {
        this.style.background = 'rgba(255,255,255,0.06)';
        this.style.color = '#f1f1f1';
      }
    });

    var isFirst = (opt === cat.options[0]);
    if (isFirst) {
      btn.classList.add('filter-active');
      btn.style.background = 'rgba(255,255,255,0.18)';
      btn.style.color = '#fff';
      btn.style.fontWeight = '600';
    }

    var self = btn;
    btn.addEventListener('click', function() {
      optionsContainer.querySelectorAll('button').forEach(function(b) {
        b.classList.remove('filter-active');
        b.style.background = 'rgba(255,255,255,0.06)';
        b.style.color = '#f1f1f1';
        b.style.fontWeight = 'normal';
      });
      self.classList.add('filter-active');
      self.style.background = 'rgba(255,255,255,0.18)';
      self.style.color = '#fff';
      self.style.fontWeight = '600';
    });

    optionsContainer.appendChild(btn);
  });

  group.appendChild(optionsContainer);
  panel.appendChild(group);
});

element.appendChild(panel);
